  search: { query: "AI storybook and drawing-to-story app or products for young children aged 4 to 8, personalised children's stories", mode: 'hybrid' },
  limit: 60,
  fields: ['basic_info.name', 'basic_info.year_founded', 'basic_info.company_type', 'headcount.total', 'funding.last_round_type', 'basic_info.status']
});
if (!r.ok) return { error: r.message, status: r.status };
const cs = r.data.companies || [];
const bucket = (n) => n == null ? 'unknown' : n <= 10 ? '1-10' : n <= 50 ? '11-50' : n <= 200 ? '51-200' : '200+';
const counts = {};
const funding = {};
const founded = {};
for (const c of cs) {
