  const y = c.basic_info && c.basic_info.year_founded;
  const yb = !y ? 'unknown' : y >= 2023 ? '2023 or later' : y >= 2018 ? '2018-2022' : 'before 2018';
  founded[yb] = (founded[yb] || 0) + 1;
}
return { returned: cs.length, credits_used: r.credits_used, headcount_buckets: counts, last_funding_round: funding, founded: founded, sample_names_for_relevance_check_only: cs.slice(0, 10).map((c) => c.basic_info && c.basic_info.name) };

